.badge{
  --tint-hue:var(--tertiary-500);
  display:inline-flex;
  align-items:center;
  gap:var(--s-1);
  font-family:var(--font-sans);
  font-size:var(--t-small);
  letter-spacing:var(--tr-snug);
  padding:var(--s-2) var(--s-4);
  border-radius:var(--r-md);
  border:var(--bw-1) solid color-mix(in srgb, var(--tint-hue) calc(var(--tint-edge-deep) * 100%), transparent);
  color:var(--tertiary-300);
  background:color-mix(in srgb, var(--tint-hue) calc(var(--tint-fill-deep) * 100%), transparent);
  font-weight:500;
  white-space:nowrap;
  flex:none;
}
.badge .dot{
  width:var(--s-1);
  height:var(--s-1);
  border-radius:var(--r-full);
  background:currentColor;
}
.badge-success, .badge-warn, .badge-danger, .badge-info, .badge-brand{
  border-color:color-mix(in srgb, var(--tint-hue) calc(var(--tint-edge) * 100%), transparent);
  background:color-mix(in srgb, var(--tint-hue) calc(var(--tint-fill) * 100%), transparent);
}
.badge-success{
  --tint-hue:var(--success);
  color:var(--success);
}
.badge-warn{
  --tint-hue:var(--warning);
  color:var(--warning);
}
.badge-danger{
  --tint-hue:var(--danger);
  color:var(--danger);
}
.badge-info{
  --tint-hue:var(--info);
  color:var(--info);
}
.badge-brand{
  --tint-hue:var(--primary-500);
  color:var(--primary-400);
}
.badge-solid{
  background:var(--primary-500);
  color:var(--obsidian-050);
  border-color:var(--primary-500);
}
